public class Lesson {
    static class Mob {
        String name;
        int health;

        Mob(String name, int health) {
            this.name = name;
            this.health = health;
        }

        void describe() {
            System.out.println(name + " has " + health + " health");
        }
    }

    public static void main(String[] args) {
        Mob zombie = new Mob("Zombie", 20);
        Mob skeleton = new Mob("Skeleton", 20);
        zombie.describe();
        skeleton.describe();

        Playground.say("Placing a block above my head...");
        Playground.placeBlock(0, 2, 0, "gold_block");
        Playground.particles(0, 3, 0, "happy_villager", 15);
    }
}
